CREATE TABLE projected_works WITH (format='PARQUET',write_compression='ZSTD') AS SELECT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS work_id,w.id AS canonical_id,CASE WHEN w.publication_year BETWEEN 0 AND 65535 THEN w.publication_year END AS publication_year,w.type AS work_type,try_cast(regexp_extract(w.primary_location.source.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS source_id,coalesce(w.open_access.is_oa,false) AS is_oa,coalesce(w.is_xpac,false) AS is_xpac,cast(w.cited_by_count AS bigint) AS cited_by_count,try_cast(regexp_extract(w.primary_topic.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS primary_topic_id FROM raw_works w WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL;
